type SectionInput = { id: string; title: string; blocks: string[] };
const p = (content: string) => ({ type: "paragraph" as const, content });
const h = (content: string) => ({ type: "subheading" as const, content });
const makeChapter = (
  number: number,
  title: string,
  subtitle: string,
  sections: SectionInput[],
  exercises: WorkbookExercise[],
): BookChapter => ({
  id: String(number).padStart(2, "0"),
  number,
  title,
  subtitle,
  readingMinutes: 11,
  wordCount: sections.reduce((sum, section) => sum + section.blocks.join(" ").split(/\s+/).length, 0),
  sections: sections.map((section) => ({
    id: section.id,
    title: section.title,
    blocks: section.blocks.map((block) => p(block)),
  })),
  exercises,
});

